        String campaignId,
        int budget,
        int inFlight,
        int confirmed,
        int transferable,
        int version
) {
    public static AccountStateResponse from(AccountSnapshot snapshot) {
        return new AccountStateResponse(
                snapshot.campaignId(),
                snapshot.budget(),
                snapshot.inFlight(),
                snapshot.confirmed(),
                snapshot.transferable(),
