    }

    @Test
    @DisplayName("规则不一致 422：租户、窗口、受众规则任一不同均拒绝")
    void ruleMismatchReturns422() {
        account("req-a", "c1", 100);
        budgetService.createAccount(new CreateBudgetAccountRequest(
                "req-b", "c2", "tenant-2", WS, WE, "audience-a", 50));
